<?php
declare(strict_types=1);namespace App\Http\Controllers\TeachingAssignments;use App\Http\Controllers\Controller;use App\Models\TeachingAssignmentSet;use App\Services\TeachingAssignments\TeachingAssignmentReportService;use Illuminate\Http\Request;use Illuminate\View\View;
class MyTeachingAssignmentController extends Controller {public function __invoke(Request $request,TeachingAssignmentReportService $service):View{abort_unless($request->user()->can('teaching-assignments.view-own'),403);$personnel=$request->user()->personnel;if(!$personnel)return view('teaching-assignments.my',['personnel'=>null,'set'=>null,'report'=>null]);$set=TeachingAssignmentSet::with('academicYear')->where('status','active')->when($request->integer('set'),fn($q)=>$q->whereKey($request->integer('set')))->latest('activated_at')->first();return view('teaching-assignments.my',['personnel'=>$personnel,'set'=>$set,'report'=>$set?$service->personnel($set,$personnel):null]);}}
